import { fileURLToPath } from 'node:url';

import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { Client } from 'pg';

/** The SQL generated by drizzle-kit (`pnpm db:generate`). */
export const MIGRATIONS_DIR = fileURLToPath(new URL('../../../drizzle', import.meta.url));

/** Serialises migrators; any constant unique to this app. */
const MIGRATION_LOCK = 0x4155_5450;

/**
 * Applies the pending migrations. Runs as the schema owner, so the tables it
 * creates get the default privileges of ADR 0010. Two migrators never
 * overlap: the second waits for the first, then finds nothing to do.
 */
export async function runMigrations(url: string, folder: string = MIGRATIONS_DIR): Promise<void> {
  const client = new Client({ connectionString: url, application_name: 'autoporada-migrate' });
  await client.connect();
  try {
    await client.query('SELECT pg_advisory_lock($1)', [MIGRATION_LOCK]);
    await migrate(drizzle({ client }), { migrationsFolder: folder });
  } finally {
    // Ending the session also releases the advisory lock.
    await client.end();
  }
}
